<?php init_tail();?><script>init_datepicker();init_selectpicker();function scrDNew(){var m=jQuery('#scrDiscountModal');m.find('form')[0].reset();m.find('[name=id]').val(0);m.find('select').val('').selectpicker('refresh');jQuery('#scrDError').hide()}jQuery('.scr-d-edit').click(function(){var b=jQuery(this),m=jQuery('#scrDiscountModal');m.find('[name=id]').val(b.data('id'));m.find('[name=group_id]').val(b.data('group')).selectpicker('refresh');m.find('[name=base_percent]').val(b.data('base'));m.find('[name=max_percent]').val(b.data('max'));m.find('[name=valid_from]').val(b.data('from'));m.find('[name=valid_to]').val(b.data('to'))});jQuery('#scrDForm').on('submit',function(e){var f=jQuery(this),b=parseFloat(f.find('[name=base_percent]').val()),m=parseFloat(f.find('[name=max_percent]').val()),msg='';if(!f.find('[name=group_id]').val())msg='<?=addslashes(_l('scr_group_required'))?>';else if(isNaN(b)||isNaN(m))msg='<?=addslashes(_l('scr_percent_numeric'))?>';else if(m<b)msg='<?=addslashes(_l('scr_max_less_base'))?>';else if(!f.find('[name=valid_from]').val()||!f.find('[name=valid_to]').val())msg='<?=addslashes(_l('scr_from_required'))?>';if(msg){e.preventDefault();jQuery('#scrDError').text(msg).show()}});</script><script>
(function($){
var records=<?=json_encode($overrides??[],JSON_UNESCAPED_UNICODE|JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_AMP|JSON_HEX_QUOT)?>;
function scrSetOverrideActive(enabled){var f=$('#scrOverrideForm');f.find('[name=active]').val(enabled?'1':'0');var b=$('#scrOverrideActiveToggle');b.toggleClass('btn-success',enabled).toggleClass('btn-default',!enabled).attr('aria-pressed',enabled?'true':'false').text((enabled?'✓ ':'')+'فعال: '+(enabled?'بله':'خیر'));}
$('#scrOverrideActiveToggle').on('click',function(){scrSetOverrideActive($('#scrOverrideForm [name=active]').val()!=='1');});
$('.scr-override-open').on('click',function(){
 var b=$(this),kind=b.attr('data-kind'),rule=b.attr('data-rule'),f=$('#scrOverrideForm'),rows=(records[rule]||[]).filter(function(x){return x.kind===kind});
 f[0].reset();if(kind==='ceiling')f.find('[name=percent]').val('0');scrSetOverrideActive(true);f.find('[name=id]').val(0);f.find('[name=rule_id]').val(rule);f.find('[name=kind]').val(kind);
 $('#scrOverrideGroup').text('گروه: '+b.attr('data-group'));$('#scrOverrideModal .modal-title').text(kind==='free'?'مجوز تخفیف آزاد':(kind==='ceiling'?'مجوز افزایش تا سقف':'تخفیف جشنواره‌ای'));$('.scr-festival-dates').toggle(kind==='festival');$('#scrOverrideForm [name=percent]').closest('.form-group').toggle(kind!=='ceiling');$('#scrOverrideForm [name=percent]').prop('required',kind!=='ceiling');
 var select=$('#scrOverrideExisting').empty().append($('<option>').val('0').text('قانون جدید'));
 rows.forEach(function(x){select.append($('<option>').val(x.id).text((x.active==1?'فعال':'غیرفعال')+' | '+x.percent+'٪'+(kind==='festival'?' | '+x.valid_from+' تا '+x.valid_to:'')));});
 select.off('change').on('change',function(){var r=rows.find(function(x){return String(x.id)===String(select.val())});f.find('[name=id]').val(r?r.id:0);f.find('[name=percent]').val(r?r.percent:(kind==='ceiling'?'0':''));f.find('[name=valid_from]').val(r?r.valid_from:'');f.find('[name=valid_to]').val(r?r.valid_to:'');scrSetOverrideActive(r?String(r.active)==='1':true);});
 // Prefer the currently active saved override; otherwise open the most recent saved record.
 // The user must explicitly select 'قانون جدید' to create another festival.
 if(rows.length){
  var saved=rows.find(function(x){return String(x.active)==='1';})||rows[0];
  select.val(String(saved.id)).trigger('change');
 }
 if(kind==='ceiling'&&!rows.length)f.find('[name=percent]').val('0');$('#scrOverrideModal').modal('show');
});
$('#scrOverrideForm').on('submit',function(e){var f=$(this),p=Number(f.find('[name=percent]').val()),kind=f.find('[name=kind]').val();if(kind!=='ceiling'&&(!Number.isFinite(p)||p<0||p>100)){e.preventDefault();alert('درصد نامعتبر است.');return;}if(kind==='festival'){var a=f.find('[name=valid_from]').val(),b=f.find('[name=valid_to]').val();if(!/^\d{4}-\d{2}-\d{2}$/.test(a)||!/^\d{4}-\d{2}-\d{2}$/.test(b)||a>b){e.preventDefault();alert('بازه تاریخ میلادی نامعتبر است.');}}});
})(jQuery);
